#!/usr/bin/env python3
"""Verify unchanged pinned inputs, then deterministically generate the private ESM runtime."""
import argparse
import hashlib
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parent
EXPECTED = {'LICENSE.bootstrap.txt': '53d2513c8df48a817d70537cc906b8e9c7bf2513328ff66847894773e615b37e', 'LICENSE.grocy.txt': 'ca49d1dcaf24ce093ea748b781469a7ad2a58123a400d1a0f10a29f92ae8c218', 'LICENSE.jquery.txt': 'd4db9ebe6f29f5168eac45ad713f055623ac5d0dcd5ba92da23d650ae012020d', 'LICENSE.moment.txt': '8f38f320bbf5eb84c08e08676f7ee1d2204ebe5797f6a090d077329cf212fca3', 'LICENSE.tempusdominus.txt': 'c9f99898c9068c363171c848643145cc2533e06d3d4301ca79358686532e9e04', 'source/bootstrap.bundle.min.js': '19126b874a32753d42c12dfa6c17892bfd93820a5a5100ba1b34da4d07599b49', 'source/datetimepicker.js': '580987621654ca73d5821b0f8779f463c53752ea88caeb83b5840f5276f31a8f', 'source/datetimepicker2.js': 'e656e7c11dc7b304b495f678e700ecb0a97d8135df2e4b1d71c96bcb929049f7', 'source/jquery.min.js': 'fc9a93dd241f6b045cbff0481cf4e1901becd0e12fb45166a8f17f95823f0b1a', 'source/moment-with-locales.min.js': '69ad644b0ab4b3c39486a909655430e53a3436ef05b207b127e74da669d97325', 'source/tempusdominus-bootstrap-4.js': 'db53b824feac7ba7eecf52e0598e0c332b4d1eae7753a244ba0bd24872c4b09f', 'source/yarn.lock': 'd1a941b595abad9b766cb7c9a2caa3862da09df2f712e5be6f92e1537f555d0b', 'tempusdominus-bootstrap-4.css': '9e7cfa5ef528294f8aa5c016a242d3be205a4d1d83f0b43a760495a6435f33de'}


def digest(content):
    return hashlib.sha256(content).hexdigest()


def source(name):
    content = (ROOT / name).read_bytes()
    actual = digest(content)
    if actual != EXPECTED[name]:
        raise SystemExit(f"Pinned source mismatch: {name}: {actual}")
    return content


SOURCE_MAP_DIRECTIVES = {
    "source/bootstrap.bundle.min.js": b"//# sourceMappingURL=bootstrap.bundle.min.js.map",
    "source/moment-with-locales.min.js": b"//# sourceMappingURL=moment-with-locales.min.js.map",
}


def wrap(prefix, name, suffix):
    content = source(name)
    directive = SOURCE_MAP_DIRECTIVES.get(name)
    if directive is not None:
        if content.count(directive) != 1:
            raise SystemExit(f"Unexpected source-map directive count: {name}")
        # A standalone map cannot describe offsets inside this combined module.
        # Keep the raw input exact; omit only its non-executable map directive.
        content = content.replace(directive, b"", 1)
    if name in {"source/datetimepicker.js", "source/datetimepicker2.js"}:
        assignment = b'\tvalue = "";'
        if content.count(assignment) != 1:
            raise SystemExit(f"Unexpected native Clear publication count: {name}")
        # The classic free assignment is observable by native File Clear callbacks.
        # Keep the raw input exact and publish at this one original statement site.
        content = content.replace(assignment, b'\tpublishClearValue();\n' + assignment, 1)
    return prefix.encode("utf-8") + content + suffix.encode("utf-8")


def runtime():
    return b"".join([
        b"// Generated by generate-runtime.py. Pinned inputs retained; documented Clear publication hook inserted; standalone map directives omitted.\n",
        wrap("export function createJQuery(window) {\nconst module = { exports: {} };\nconst exports = module.exports;\nconst document = window.document;\n(function (module, exports, window, document) {\n", "source/jquery.min.js", "\n}).call(window, module, exports, window, document);\nreturn module.exports;\n}\n"),
        wrap("export function createMoment() {\nconst module = { exports: {} };\nconst exports = module.exports;\nconst require = (name) => { throw new Error('Unbundled Moment locale: ' + name); };\n(function (module, exports, require) {\n", "source/moment-with-locales.min.js", "\n}).call(undefined, module, exports, require);\nreturn module.exports;\n}\n"),
        wrap("export function installBootstrap(jQuery, window, document) {\nconst module = { exports: {} };\nconst exports = module.exports;\nconst require = (name) => { if (name === 'jquery') return jQuery; throw new Error('Unbundled Bootstrap dependency: ' + name); };\n(function (module, exports, require, jQuery, window, document) {\n", "source/bootstrap.bundle.min.js", "\n}).call(window, module, exports, require, jQuery, window, document);\nreturn module.exports;\n}\n"),
        wrap("export function installTempus(jQuery, moment, window, document) {\n", "source/tempusdominus-bootstrap-4.js", "\nreturn jQuery.fn.datetimepicker;\n}\n"),
        wrap("export function installDateTimePicker1($, moment, Grocy, RefreshContextualTimeago, publishClearValue = () => {}) {\n// The classic source Clear assignment has an explicit document-owned publication hook.\nvar value;\n", "source/datetimepicker.js", "\nreturn Grocy.Components.DateTimePicker;\n}\n"),
        wrap("export function installDateTimePicker2($, moment, Grocy, RefreshContextualTimeago, publishClearValue = () => {}) {\n// The classic source Clear assignment stays within this private module owner.\nvar value;\n", "source/datetimepicker2.js", "\nreturn Grocy.Components.DateTimePicker2;\n}\n"),
    ])


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true", help="verify without writing outputs")
    args = parser.parse_args()
    for name in EXPECTED:
        source(name)
    generated = runtime()
    if args.check:
        if (ROOT / "runtime.js").read_bytes() != generated:
            raise SystemExit("runtime.js is not the deterministic wrapper of the pinned inputs")
    else:
        (ROOT / "runtime.js").write_bytes(generated)
    names = sorted([*EXPECTED, "runtime.js", "generate-runtime.py", "provenance.json", "README.md"])
    assets = {name: digest((ROOT / name).read_bytes()) for name in names}
    manifest = (json.dumps({"grocy_commit": "21aa5eab218c8466f90729154cb293fffbe10c21", "assets": assets}, indent=2) + "\n").encode()
    sums = "".join(f"{value}  {name}\n" for name, value in assets.items())
    sums += f"{digest(manifest)}  ASSET-MANIFEST.json\n"
    if args.check:
        if (ROOT / "ASSET-MANIFEST.json").read_bytes() != manifest:
            raise SystemExit("ASSET-MANIFEST.json differs")
        if (ROOT / "SHA256SUMS").read_bytes() != sums.encode():
            raise SystemExit("SHA256SUMS differs")
    else:
        (ROOT / "ASSET-MANIFEST.json").write_bytes(manifest)
        (ROOT / "SHA256SUMS").write_bytes(sums.encode())
    print(f"Verified {len(EXPECTED)} pinned inputs and {len(assets)} runtime assets")


if __name__ == "__main__":
    main()
